// Findet die Parameterform fuer das Blaettern der Buchungsliste.
// Nur Lesezugriffe. Ausgegeben werden Anzahlen, das Huellenfeld limit und
// jeweils die erste und letzte Buchungs-ID zum Vergleich der Seiten.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2/booking/list';

function auswerten(body) {
  const roh = body?.data;
  const liste = roh && typeof roh === 'object' && !Array.isArray(roh) ? Object.entries(roh) : [];
  const ids = liste.map(([k, v]) => (v && typeof v === 'object' ? v.id ?? k : k));
  const zeiten = liste.map(([, v]) => (v && typeof v === 'object' ? v.time ?? null : null));
  return {
    anzahl: liste.length,
    erste_id: ids[0] ?? null,
    letzte_id: ids.length ? ids[ids.length - 1] : null,
    erste_zeit: zeiten[0] ?? null,
    letzte_zeit: zeiten.length ? zeiten[zeiten.length - 1] : null,
    limit_huelle: body?.limit === undefined ? '-' : JSON.stringify(body.limit).slice(0, 200),
  };
}

async function abruf(bezeichnung, optionen) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: optionen.method ?? 'GET',
      url: basis,
      headers,
      qs: optionen.qs,
      body: optionen.body,
      json: true,
      returnFullResponse: true,
      timeout: 30000,
    });
    return { variante: bezeichnung, status: antwort.statusCode, ...auswerten(antwort.body) };
  } catch (fehler) {
    return {
      variante: bezeichnung,
      status: fehler?.response?.status ?? fehler?.httpCode ?? 'kein Status',
      anzahl: 0,
      fehlermeldung: String(fehler?.message ?? fehler).slice(0, 200),
    };
  }
}

const hole = abruf.bind(this);

const varianten = [
  ['A Grundabruf', {}],
  ['B JSON-Koerper Seite 1', { body: { limit: { start: 0, reply: 10 }, order: { time: 'DESC' } } }],
  ['C JSON-Koerper Seite 2', { body: { limit: { start: 10, reply: 10 }, order: { time: 'DESC' } } }],
  ['D JSON-Koerper aufsteigend', { body: { limit: { start: 0, reply: 10 }, order: { time: 'ASC' } } }],
  ['E Query als JSON-Text S1', { qs: { limit: JSON.stringify({ start: 0, reply: 10 }), order: JSON.stringify({ time: 'DESC' }) } }],
  ['F Query als JSON-Text S2', { qs: { limit: JSON.stringify({ start: 10, reply: 10 }), order: JSON.stringify({ time: 'DESC' }) } }],
  ['G POST mit JSON-Koerper S1', { method: 'POST', body: { limit: { start: 0, reply: 10 }, order: { time: 'DESC' } } }],
  ['H POST mit JSON-Koerper S2', { method: 'POST', body: { limit: { start: 10, reply: 10 }, order: { time: 'DESC' } } }],
];

const ergebnisse = [];
for (const [bezeichnung, optionen] of varianten) {
  ergebnisse.push(await hole(bezeichnung, optionen));
}

const grund = ergebnisse[0];

return ergebnisse.map((e) => ({
  json: {
    schritt: 'S6',
    variante: e.variante,
    status: e.status,
    anzahl: e.anzahl,
    wie_grundabruf: e.erste_id && grund?.erste_id ? e.erste_id === grund.erste_id : '-',
    erste_id: e.erste_id ?? '-',
    letzte_id: e.letzte_id ?? '-',
    limit_huelle: e.limit_huelle ?? '-',
    fehlermeldung: e.fehlermeldung ?? '-',
  },
}));
